let S, adminKey='', activeTab='Dashboard', editingId=null, importRows=[], adminFilters={q:'',status:'',decree:'',altar:'',missing:'',atmo:'',sort:'updated'};
(async function(){ S=await loadShared(); applyThemeVars(S); renderLogin(); })();
function renderLogin(){ $('#adminApp').innerHTML=`<main class="admin-wrap"><header class="admin-hero"><img src="${esc(assetUrl(S.settings.sanctumLogo))}" alt=""><div><p class="eyebrow">Sanctum Admin</p><h1>Archivist Console</h1><p class="muted">Manage the Emberlight Sanctum.</p></div></header><section class="panel"><h2>Unlock Admin</h2><p class="muted">Enter your Netlify ADMIN_KEY.</p><input id="adminKey" type="password" placeholder="Admin key"><button id="unlock" class="btn primary">Unlock</button><p id="msg" class="warn"></p></section></main>`; $('#unlock').onclick=async()=>{const entered=$('#adminKey').value.trim(); const msg=$('#msg'); if(!entered) return msg.textContent='Enter admin key.'; msg.textContent='Checking...'; try{ const r=await fetch(SANCTUM.authEndpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({key:entered})}); if(!r.ok){ adminKey=''; msg.textContent='Access denied.'; return; } adminKey=entered; renderAdmin(); }catch(e){ adminKey=''; msg.textContent='Unable to verify admin key. Please try again.'; } }; }
function renderAdmin(){ $('#adminApp').innerHTML=`<main class="admin-wrap"><header class="admin-hero"><img src="${esc(assetUrl(S.settings.sanctumLogo))}" alt=""><div><p class="eyebrow">The Emberlight Sanctum</p><h1>Archivist Console</h1></div></header><nav class="admin-nav">${['Dashboard','Records','Imports','Ember Altar','Threads','Messages','Atmospheres & Audio','Settings'].map(t=>`<button data-tab="${t}" class="${activeTab===t?'active':''}">${t}</button>`).join('')}<a class="btn ghost" href="/" target="_blank">View Site</a></nav><section id="view"></section></main>`; $$('[data-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab; editingId=null; renderAdmin();}); renderTab(); }
function renderTab(){ const v=$('#view'); if(activeTab==='Dashboard') v.innerHTML=dashboard(); if(activeTab==='Records') v.innerHTML=recordsTab(); if(activeTab==='Imports') v.innerHTML=importsTab(); if(activeTab==='Ember Altar') v.innerHTML=altarTab(); if(activeTab==='Threads') v.innerHTML=collectionsTab(); if(activeTab==='Messages') v.innerHTML=messagesTab(); if(activeTab==='Atmospheres & Audio') v.innerHTML=atmoTab(); if(activeTab==='Settings') v.innerHTML=settingsTab(); wireTab(); }
async function persist(label='Saved'){ try{ S.updatedAt=new Date().toISOString(); await saveShared(S, adminKey); toast(label); }catch(e){ alert('Save failed: '+e.message); } }
function toast(t){ let el=$('#toast'); if(!el){el=document.createElement('p');el.id='toast';el.className='ok';document.body.appendChild(el);} el.textContent=t; el.classList.add('show'); clearTimeout(el._timer); el._timer=setTimeout(()=>{el.classList.remove('show'); el.textContent='';},3200); }
function dashboard(){ const pubs=publicRecords(S); return `<section class="panel"><h2>Dashboard</h2><div class="stat-grid">${stat('Total Records',S.records.length,'all')}${stat('Published',S.records.filter(r=>r.publicationStatus==='Published').length,'status:Published')}${stat('Hidden',S.records.filter(r=>r.publicationStatus==='Hidden').length,'status:Hidden')}${stat('Drafts',S.records.filter(r=>r.publicationStatus==='Draft').length,'status:Draft')}${stat('Gilded',S.records.filter(r=>r.decree==='Gilded').length,'decree:Gilded')}${stat('Sterling',S.records.filter(r=>r.decree==='Sterling').length,'decree:Sterling')}${stat('Honored',pubs.filter(r=>r.altarStatus==='Honored Record').length,'altar:Honored Record')}${stat('Burning Bright',pubs.filter(r=>r.altarStatus==='Burning Bright').length,'altar:Burning Bright')}${stat('Threads',(S.collections||[]).length,'collections')}${stat('Messages',(S.messages||[]).length,'messages')}</div><div id="analyticsPanel" class="analytics-panel"></div><div class="toolbar"><button class="btn primary" id="addQuick">Add Record</button><button class="btn ghost" id="exportCsv">Export CSV</button><button class="btn ghost" id="exportJson">Export JSON Backup</button></div><p class="muted">Last updated: ${esc(S.updatedAt||'')}</p></section>`; }
function stat(k,v,filter){return `<button class="stat stat-click" data-stat-filter="${esc(filter)}"><span>${esc(k)}</span><strong>${esc(v)}</strong></button>`;}
function recordsTab(){ if(editingId) return recordEditor(S.records.find(r=>r.id===editingId)); return `<section class="panel"><h2>Records</h2><div class="toolbar record-tools"><button class="btn primary" id="addRecord">Add Record</button><input id="recordSearch" placeholder="Search title or author..." value="${esc(adminFilters.q)}"><select id="statusFilter"><option value="">All status</option>${PUB_STATUS.map(x=>`<option ${adminFilters.status===x?'selected':''}>${x}</option>`).join('')}</select><select id="decreeFilter"><option value="">All decrees</option><option ${adminFilters.decree==='Gilded'?'selected':''}>Gilded</option><option ${adminFilters.decree==='Sterling'?'selected':''}>Sterling</option></select><select id="altarFilter"><option value="">All altar status</option>${ALTAR_STATUS.map(x=>`<option ${adminFilters.altar===x?'selected':''}>${x}</option>`).join('')}</select><select id="missingFilter"><option value="">Missing content</option><option value="cover" ${adminFilters.missing==='cover'?'selected':''}>Missing cover</option><option value="premise" ${adminFilters.missing==='premise'?'selected':''}>Missing premise</option><option value="granted" ${adminFilters.missing==='granted'?'selected':''}>Missing Granted Entry</option><option value="affiliate" ${adminFilters.missing==='affiliate'?'selected':''}>Missing affiliate link</option></select><select id="atmoFilter"><option value="">All atmospheres</option><option ${adminFilters.atmo==='Auto'?'selected':''}>Auto</option>${ATMOS.map(x=>`<option ${adminFilters.atmo===x?'selected':''}>${x}</option>`).join('')}</select><select id="sortFilter"><option value="updated" ${adminFilters.sort==='updated'?'selected':''}>Latest updated</option><option value="created" ${adminFilters.sort==='created'?'selected':''}>Latest created</option><option value="title" ${adminFilters.sort==='title'?'selected':''}>Title A-Z</option><option value="author" ${adminFilters.sort==='author'?'selected':''}>Author A-Z</option></select><button class="btn ghost" id="clearRecordFilters">Clear Filters</button></div><div id="recordList" class="record-admin-list"></div></section>`; }
function recordList(){ let arr=[...S.records]; const q=norm(adminFilters.q); if(q) arr=arr.filter(r=>norm(`${r.title} ${r.author}`).includes(q)); if(adminFilters.status) arr=arr.filter(r=>r.publicationStatus===adminFilters.status); if(adminFilters.decree) arr=arr.filter(r=>r.decree===adminFilters.decree); if(adminFilters.altar) arr=arr.filter(r=>normalizedAltar(r.altarStatus)===adminFilters.altar); if(adminFilters.atmo) arr=arr.filter(r=>(r.atmosphere||'Auto')===adminFilters.atmo); if(adminFilters.missing){ arr=arr.filter(r=>{ if(adminFilters.missing==='cover') return !coverFor(r); if(adminFilters.missing==='premise') return !clean(r.premise); if(adminFilters.missing==='granted') return !clean(r.grantedEntryBecause); if(adminFilters.missing==='affiliate') return !parseLinks(r).length; return false; }); } arr.sort((a,b)=>{ if(adminFilters.sort==='title') return String(a.title).localeCompare(b.title); if(adminFilters.sort==='author') return String(a.author).localeCompare(b.author); if(adminFilters.sort==='created') return String(b.createdAt||'').localeCompare(a.createdAt||''); return String(b.updatedAt||'').localeCompare(a.updatedAt||''); }); return arr.map(r=>`<div class="admin-row"><img src="${esc(assetUrl(coverFor(r)||'assets/logos/favicon.png'))}" alt=""><div><strong>${esc(r.title||'Untitled')}</strong><div class="muted">${esc(r.author||'')} · <span class="pill">${esc(r.decree||'No decree')}</span><span class="pill">${esc(r.publicationStatus)}</span><span class="pill">${esc(normalizedAltar(r.altarStatus))}</span></div></div><div class="toolbar"><button class="btn small" onclick="editRecord('${r.id}')">Edit</button><button class="btn small" onclick="copyLink('${r.id}')">Copy Link</button><button class="btn small" onclick="previewRecord('${r.id}')">Preview</button><button class="btn small danger" onclick="deleteRecord('${r.id}')">Delete</button></div></div>`).join('')||'<p class="muted">No records.</p>'; }
window.editRecord=id=>{editingId=id; renderAdmin();}; window.previewRecord=id=>{const r=S.records.find(x=>x.id===id); if(r) window.open(`/records/${recordSlug(r)}`,'_blank');}; window.copyLink=async id=>{const r=S.records.find(x=>x.id===id); const url=location.origin+`/records/${recordSlug(r)}`; await navigator.clipboard.writeText(url); toast('Record link copied.');}; window.deleteRecord=async id=>{if(confirm('Delete this record?')){S.records=S.records.filter(r=>r.id!==id); await persist('Record deleted.'); renderAdmin();}};
function recordEditor(r){ r = r || newRecord(); const isNew=!S.records.find(x=>x.id===r.id); const warnings=publishWarnings(r); return `<section class="panel"><button class="btn ghost" id="backRecords">← Back to Records</button><h2>${isNew?'Add Record':'Edit Record'}</h2>${warnings.length?`<div class="panel warn"><strong>Publishing warnings</strong><ul>${warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div>`:''}<div class="tabs">${['Core','Sanctum Content','Series','Additional Fields','Atmosphere','Seek the Record','Publishing'].map((t,i)=>`<button class="edit-tab ${i===0?'active':''}" data-edit-tab="${t}">${t}</button>`).join('')}</div><form id="recordForm">${editorSections(r)}<div class="toolbar"><button class="btn primary">Save Record</button></div></form></section>`; }
function newRecord(){return migrateRecord({id:uid(),title:'',author:'',decree:'Gilded',publicationStatus:'Draft',altarStatus:'None',atmosphere:'Auto',overlayColor:'Auto',overlayOpacity:'Auto',createdAt:new Date().toISOString()});}
function collectionOptionsForRecord(r){ const active=S.collections||[]; if(!active.length) return '<p class="muted">No threads created yet.</p>'; return `<div class="check-grid">${active.map(c=>`<label class="check"><input type="checkbox" name="collections" value="${esc(c.id)}" ${r.collections?.includes(c.id)?'checked':''}> ${esc(c.name)} <span class="muted">${esc(c.status||'Active')}</span></label>`).join('')}</div>`; }
function additionalRows(r){ const fields=parseAdditionalFields(r.additionalFields); const rows=[...fields]; while(rows.length<10) rows.push({label:'',value:''}); return rows.map((f,i)=>`<div class="grid2 additional-row"><label>Field ${i+1} Label<input name="additionalLabel${i}" value="${esc(f.label)}" placeholder="Narrator"></label><label>Field ${i+1} Value<input name="additionalValue${i}" value="${esc(f.value)}" placeholder="Elizabeth Evans"></label></div>`).join(''); }
function editorSections(r){ const atOpts=['Auto',...ATMOS].map(a=>`<option ${r.atmosphere===a?'selected':''}>${a}</option>`).join(''); const colors=['Auto','Gold','Plum','Silver','Blue','Forest','Crimson','Custom'].map(a=>`<option ${r.overlayColor===a?'selected':''}>${a}</option>`).join(''); const seriesOpts=['','Standalone','In Progress','Complete'].map(a=>`<option value="${esc(a)}" ${r.seriesStatus===a?'selected':''}>${a||'Select status'}</option>`).join(''); return `<div data-section="Core" class="edit-section"><div class="grid2"><label>Title<input name="title" required value="${esc(r.title)}"></label><label>Author<input name="author" required value="${esc(r.author)}"></label><label>Cover URL<input name="coverUrl" value="${esc(r.coverUrl)}"></label><label>Upload Cover<input id="coverUpload" type="file" accept="image/*"></label></div>${r.coverUrl?`<img class="cover-preview" src="${esc(assetUrl(r.coverUrl))}">`:''}<div class="grid3"><label>Decree<select name="decree"><option ${r.decree==='Gilded'?'selected':''}>Gilded</option><option ${r.decree==='Sterling'?'selected':''}>Sterling</option></select></label><label>Publication Status<select name="publicationStatus">${PUB_STATUS.map(x=>`<option ${r.publicationStatus===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Custom Slug<input name="customSlug" value="${esc(r.customSlug)}"></label></div></div><div data-section="Sanctum Content" class="edit-section hidden"><label>${esc(labelFor('premise'))}<textarea name="premise">${esc(r.premise)}</textarea></label><label>${esc(labelFor('grantedEntryBecause'))}<textarea name="grantedEntryBecause">${esc(r.grantedEntryBecause)}</textarea></label><label>${esc(labelFor('featuredQuote'))}<textarea name="featuredQuote">${esc(r.featuredQuote)}</textarea></label><label>${esc(labelFor('lingeringEchoes'))} <span class="muted">separate with ||</span><textarea name="lingeringEchoes">${esc(splitEchoes(r.lingeringEchoes).join(' || '))}</textarea></label><label>${esc(labelFor('hiddenEmber'))}<textarea name="hiddenEmber">${esc(r.hiddenEmber)}</textarea></label><label>${esc(labelFor('hiddenBeyondTheVeil'))}<textarea name="hiddenBeyondTheVeil">${esc(r.hiddenBeyondTheVeil)}</textarea></label><h3>Threads</h3>${collectionOptionsForRecord(r)}</div><div data-section="Series" class="edit-section hidden"><div class="grid2"><label>Series Name<input name="seriesName" value="${esc(r.seriesName)}"></label><label>Book Number<input name="bookNumber" value="${esc(r.bookNumber)}" placeholder="1, 2, 3..."></label><label>Series Status<select name="seriesStatus">${seriesOpts}</select></label></div><label>Series Note<textarea name="seriesNote">${esc(r.seriesNote)}</textarea></label></div><div data-section="Additional Fields" class="edit-section hidden"><p class="section-note">Optional per-record fields. Only filled rows appear publicly.</p>${additionalRows(r)}</div><div data-section="Atmosphere" class="edit-section hidden"><div class="grid3"><label>Atmosphere<select name="atmosphere">${atOpts}</select></label><label>Overlay Color<select name="overlayColor">${colors}</select></label><label>Overlay Opacity<input name="overlayOpacity" value="${esc(r.overlayOpacity)}" placeholder="Auto or 0.75"></label></div><div class="grid2"><label>Spotify URL<input name="spotifyUrl" value="${esc(r.spotifyUrl)}"></label><label>Custom Audio URL<input name="customAudioUrl" value="${esc(r.customAudioUrl)}"></label></div><button type="button" class="btn ghost" id="restoreAuto">Restore Automatic Settings</button><button type="button" class="btn ghost" id="restoreSaved">Restore Last Saved</button></div><div data-section="Seek the Record" class="edit-section hidden"><div class="grid3">${['amazonUS','amazonCA','amazonUK','amazonIN','amazonAU','bookshopUS','bookshopUK','indigo','goodreads','authorWebsite'].map(k=>`<label>${k}<input name="${k}" value="${esc(r[k])}"></label>`).join('')}</div><h3>Custom Links</h3><div class="grid2">${[1,2,3].map(i=>`<label>Custom Link ${i} Label<input name="customLink${i}Label" value="${esc(r[`customLink${i}Label`])}"></label><label>Custom Link ${i} URL<input name="customLink${i}Url" value="${esc(r[`customLink${i}Url`])}"></label>`).join('')}</div></div><div data-section="Publishing" class="edit-section hidden"><div class="grid2"><label>Altar Display Status<input readonly value="${esc(normalizedAltar(r.altarStatus))}"></label><label>Altar Sort Order<input readonly value="${esc(r.sortOrder||'')}"></label></div><input type="hidden" name="altarStatus" value="${esc(r.altarStatus||'None')}"><input type="hidden" name="sortOrder" value="${esc(r.sortOrder||'')}"><p class="section-note">Homepage highlights are managed only in the Ember Altar tab.</p></div><input type="hidden" name="id" value="${esc(r.id)}">`; }
function publishWarnings(r){ const w=[]; if(r.publicationStatus==='Published'){ if(!clean(r.coverUrl)) w.push('Published record has no cover.'); if(!clean(r.premise)) w.push('Published record has no premise.'); if(!clean(r.grantedEntryBecause)) w.push('Published record has no Granted Entry Because.'); } return w; }
function publishWarnings(r){ const w=[]; if(r.publicationStatus==='Published'){ if(!clean(r.coverUrl)) w.push('Published record has no cover.'); if(!clean(r.premise)) w.push('Published record has no premise.'); if(!clean(r.grantedEntryBecause)) w.push('Published record has no Granted Entry Because.'); } return w; }
function collectRecord(form){ const fd=new FormData(form); const data=Object.fromEntries(fd.entries()); const existing=S.records.find(x=>x.id===data.id); data.collections=fd.getAll('collections'); data.additionalFields=[]; for(let i=0;i<10;i++){ const label=clean(fd.get('additionalLabel'+i)); const value=clean(fd.get('additionalValue'+i)); if(label||value) data.additionalFields.push({label,value}); } data.lingeringEchoes=splitEchoes(data.lingeringEchoes); data.altarStatus = data.altarStatus || existing?.altarStatus || 'None'; data.sortOrder = data.sortOrder!==undefined && data.sortOrder!=='' ? Number(data.sortOrder) : (existing?.sortOrder || ''); return migrateRecord(data); }
function wireTab(){ if(activeTab==='Dashboard'){ $('#addQuick').onclick=()=>{activeTab='Records';editingId=uid();S.records.push(newRecordWithId(editingId));renderAdmin();}; $('#exportCsv').onclick=()=>downloadFile('sanctum-records.csv',toCSV(S.records),'text/csv'); $('#exportJson').onclick=()=>downloadJSON('sanctum-backup.json',S); $$('[data-stat-filter]').forEach(b=>b.onclick=()=>{const f=b.dataset.statFilter; if(f==='collections'){activeTab='Threads';renderAdmin();return;} if(f==='messages'){activeTab='Messages';renderAdmin();return;} adminFilters={q:'',status:'',decree:'',altar:'',missing:'',atmo:'',sort:'updated'}; if(f!=='all'){const [k,v]=f.split(':'); adminFilters[k]=v;} activeTab='Records'; renderAdmin();}); loadAnalytics('30').then(d=>{ const box=$('#analyticsPanel'); if(box){ box.innerHTML=analyticsPanel(d); wireAnalyticsControls(d); }}).catch(e=>{ const box=$('#analyticsPanel'); if(box) box.innerHTML='<p class="warn">Analytics unavailable.</p>';}); } if(activeTab==='Records') wireRecords(); if(activeTab==='Imports') wireImports(); if(activeTab==='Ember Altar') wireAltar(); if(activeTab==='Threads') wireCollections(); if(activeTab==='Messages') wireMessagesAdmin(); if(activeTab==='Atmospheres & Audio') wireAtmo(); if(activeTab==='Settings') wireSettings(); }
function newRecordWithId(id){ const r=newRecord(); r.id=id; return r; }
function wireRecords(){ if(!editingId){ $('#addRecord').onclick=()=>{const r=newRecord(); S.records.unshift(r); editingId=r.id; renderAdmin();}; const redraw=()=>$('#recordList').innerHTML=recordList(); $('#recordSearch').oninput=e=>{adminFilters.q=e.target.value;redraw();}; $('#statusFilter').onchange=e=>{adminFilters.status=e.target.value;redraw();}; $('#decreeFilter').onchange=e=>{adminFilters.decree=e.target.value;redraw();}; $('#altarFilter').onchange=e=>{adminFilters.altar=e.target.value;redraw();}; $('#missingFilter').onchange=e=>{adminFilters.missing=e.target.value;redraw();}; $('#atmoFilter').onchange=e=>{adminFilters.atmo=e.target.value;redraw();}; $('#sortFilter').onchange=e=>{adminFilters.sort=e.target.value;redraw();}; $('#clearRecordFilters').onclick=()=>{adminFilters={q:'',status:'',decree:'',altar:'',missing:'',atmo:'',sort:'updated'};renderAdmin();}; redraw(); return; } $('#backRecords').onclick=()=>{editingId=null;renderAdmin();}; $$('[data-edit-tab]').forEach(b=>b.onclick=()=>{$$('[data-edit-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('.edit-section').forEach(s=>s.classList.toggle('hidden',s.dataset.section!==b.dataset.editTab));}); $('#restoreAuto')?.addEventListener('click',()=>{const f=$('#recordForm'); f.atmosphere.value='Auto'; f.overlayColor.value='Auto'; f.overlayOpacity.value='Auto';}); $('#restoreSaved')?.addEventListener('click',()=>renderAdmin()); $('#coverUpload')?.addEventListener('change',uploadCover); $('#recordForm').onsubmit=async e=>{e.preventDefault(); const r=collectRecord(e.target); const dup=S.records.find(x=>x.id!==r.id && keyFor(x)===keyFor(r)); if(dup){ alert(`A record already exists for ${r.title} by ${r.author}. Duplicate records are not allowed.`); return; } const warnings=publishWarnings(r); if(warnings.length && !confirm('This published record has warnings:\n\n'+warnings.join('\n')+'\n\nSave anyway?')) return; if(r.altarStatus==='Honored Record') S.records.forEach(x=>{ if(x.id!==r.id && x.altarStatus==='Honored Record') x.altarStatus='None'; }); const idx=S.records.findIndex(x=>x.id===r.id); r.updatedAt=new Date().toISOString(); if(idx>=0) S.records[idx]=r; else S.records.unshift(r); await persist('Record saved.'); editingId=r.id; renderAdmin();}; }
async function uploadCover(e){ const file=e.target.files[0]; if(!file)return; const c=S.settings.cloudinary?.cloudName, p=S.settings.cloudinary?.uploadPreset; if(!c||!p){ alert('Add Cloudinary cloud name and unsigned upload preset in Settings first.'); return; } const fd=new FormData(); fd.append('file',file); fd.append('upload_preset',p); const r=await fetch(`https://api.cloudinary.com/v1_1/${c}/image/upload`,{method:'POST',body:fd}); const j=await r.json(); if(j.secure_url){ $('#recordForm').coverUrl.value=j.secure_url; toast('Cover uploaded.'); } else alert('Upload failed: '+JSON.stringify(j)); }
async function uploadCloudinary(file, resourceType='image'){ const c=S.settings.cloudinary?.cloudName, p=S.settings.cloudinary?.uploadPreset; if(!c||!p){ alert('Add Cloudinary cloud name and unsigned upload preset in Settings first.'); return ''; } const fd=new FormData(); fd.append('file',file); fd.append('upload_preset',p); const r=await fetch(`https://api.cloudinary.com/v1_1/${c}/${resourceType}/upload`,{method:'POST',body:fd}); const j=await r.json(); if(j.secure_url) return j.secure_url; alert('Upload failed: '+JSON.stringify(j)); return ''; }
function uploadButton(id,label,accept='image/*'){return `<label class="btn ghost media-upload">${label}<input id="${id}" type="file" accept="${accept}" hidden></label>`;}
function importsTab(){ return `<section class="panel"><h2>Imports</h2><p class="section-note">Upload CSV or Excel using the locked Sanctum schema. Default mode imports only Gilded/Sterling rows.</p><div class="toolbar"><label class="btn ghost">Choose File<input id="importFile" type="file" accept=".csv,.xlsx,.xls" hidden></label><button class="btn ghost" id="downloadTemplate">Download CSV Template</button><button class="btn ghost" id="exportRecords">Export Current Records CSV</button></div><label class="check"><input type="checkbox" id="importAll"> Import all valid rows, not only Gilded/Sterling</label><div id="importSummary"></div><div id="importPreview" class="preview-table"></div><button id="confirmImport" class="btn primary hidden">Confirm Import</button></section>`; }
function wireImports(){ $('#downloadTemplate').onclick=()=>downloadFile('sanctum-template.csv',FINAL_COLUMNS.join(',')+'\n','text/csv'); $('#exportRecords').onclick=()=>downloadFile('sanctum-records.csv',toCSV(S.records),'text/csv'); $('#importFile').onchange=handleImport; $('#confirmImport').onclick=confirmImport; }
async function handleImport(e){ const f=e.target.files[0]; if(!f)return; const rows=await readImportFile(f); const importAll=$('#importAll').checked; const allRows=rows.map(rowToRecord).filter(Boolean); importRows=allRows.filter(r=>importAll||PUBLIC_DECREES.includes(r.decree)); const existing=new Map(S.records.map(r=>[keyFor(r),r])); const seen=new Set(); const stats={rows:rows.length,eligible:importRows.length,new:0,update:0,skip:0,errors:0,gilded:0,sterling:0,published:0,hidden:0,draft:0,missingCover:0,missingGranted:0,internalDup:0}; const previews=[]; importRows.forEach((r,i)=>{ const k=keyFor(r); const dup=existing.get(k); const internal=seen.has(k); seen.add(k); if(r.decree==='Gilded') stats.gilded++; if(r.decree==='Sterling') stats.sterling++; if(r.publicationStatus==='Published') stats.published++; if(r.publicationStatus==='Hidden') stats.hidden++; if(r.publicationStatus==='Draft') stats.draft++; if(!coverFor(r)) stats.missingCover++; if(!clean(r.grantedEntryBecause)) stats.missingGranted++; if(internal){stats.internalDup++; stats.errors++;} else if(dup){stats.update++;} else {stats.new++;} previews.push({r,i,dup,internal}); }); $('#importSummary').innerHTML=`<div class="import-stats"><strong>Upload Preview</strong><span>Rows: ${stats.rows}</span><span>Eligible: ${stats.eligible}</span><span>New: ${stats.new}</span><span>Updates: ${stats.update}</span><span>Gilded: ${stats.gilded}</span><span>Sterling: ${stats.sterling}</span><span>Published: ${stats.published}</span><span>Hidden: ${stats.hidden}</span><span>Draft: ${stats.draft}</span><span>Missing covers: ${stats.missingCover}</span><span>Missing Granted Entry: ${stats.missingGranted}</span><span>Duplicate rows in upload: ${stats.internalDup}</span></div>${stats.internalDup?'<p class="warn">Duplicate rows exist inside this upload. They must be skipped or corrected before import.</p>':''}`; $('#importPreview').innerHTML=previews.map(({r,i,dup,internal})=>`<div class="preview-row ${internal?'warn-row':''}"><img src="${esc(assetUrl(coverFor(r)||'assets/logos/favicon.png'))}" alt=""><div><strong>${esc(r.title)}</strong><div class="muted">${esc(r.author)} · ${esc(r.decree)} · ${esc(r.publicationStatus)}</div>${publishWarnings(r).length?`<div class="warn">${publishWarnings(r).join(' ')}</div>`:''}${internal?'<div class="warn">Duplicate row in uploaded file.</div>':''}</div><span class="pill">${internal?'Duplicate':dup?'Update':'New'}</span><select data-import-mode="${i}">${dup?'<option value="update">Update existing</option>':''}${!dup&&!internal?'<option value="new">Import</option>':''}<option value="skip">Skip</option></select></div>`).join('')||'<p class="muted">No eligible rows.</p>'; $('#confirmImport').classList.toggle('hidden',!importRows.length); }
async function readImportFile(file){ const buf=await file.arrayBuffer(); if(file.name.match(/\.xlsx?$/i) && window.XLSX){ const wb=XLSX.read(buf,{type:'array'}); return XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''}); } const text=new TextDecoder().decode(buf); return parseCSV(text); }
function parseCSV(text){ const rows=[], lines=text.split(/\r?\n/).filter(Boolean); const headers=splitCSV(lines.shift()||''); for(const line of lines){ const vals=splitCSV(line), obj={}; headers.forEach((h,i)=>obj[h]=vals[i]||''); rows.push(obj);} return rows; }
function splitCSV(line){ const out=[]; let cur='', q=false; for(let i=0;i<line.length;i++){const c=line[i]; if(c==='"'){ if(q&&line[i+1]==='"'){cur+='"';i++;} else q=!q;} else if(c===','&&!q){out.push(cur);cur='';} else cur+=c;} out.push(cur); return out.map(clean); }
function rowToRecord(row){
  const aliases={
    title:['title','book title'], author:['author'], coverUrl:['coverUrl','cover url','cover','cover image','cover image url'], decree:['decree'], publicationStatus:['publicationStatus','publication status','status'], seriesName:['seriesName','series name','series'], bookNumber:['bookNumber','book number','series number'], seriesStatus:['seriesStatus','series status'], seriesNote:['seriesNote','series note'], premise:['premise','the premise'], grantedEntryBecause:['grantedEntryBecause','granted entry because','granted entry','note','archivist note'], featuredQuote:['featuredQuote','featured quote','quote'], lingeringEchoes:['lingeringEchoes','lingering echoes','echoes'], hiddenEmber:['hiddenEmber','hidden ember'], hiddenBeyondTheVeil:['hiddenBeyondTheVeil','hidden beyond the veil','spoilers','spoiler'], additionalFields:['additionalFields','additional fields','additional notes'], collections:['collections','threads','thread'], atmosphere:['atmosphere'], overlayColor:['overlayColor','overlay color'], overlayOpacity:['overlayOpacity','overlay opacity'], spotifyUrl:['spotifyUrl','spotify url'], customAudioUrl:['customAudioUrl','custom audio url'], altarStatus:['altarStatus','altar status'], customSlug:['customSlug','custom slug','slug'], sortOrder:['sortOrder','sort order'], amazonUS:['amazonUS','amazon us'], amazonCA:['amazonCA','amazon ca'], amazonUK:['amazonUK','amazon uk'], amazonIN:['amazonIN','amazon in'], amazonAU:['amazonAU','amazon au'], bookshopUS:['bookshopUS','bookshop us'], bookshopUK:['bookshopUK','bookshop uk'], indigo:['indigo'], goodreads:['goodreads'], authorWebsite:['authorWebsite','author website'], customLink1Label:['customLink1Label','custom link 1 label'], customLink1Url:['customLink1Url','custom link 1 url'], customLink2Label:['customLink2Label','custom link 2 label'], customLink2Url:['customLink2Url','custom link 2 url'], customLink3Label:['customLink3Label','custom link 3 label'], customLink3Url:['customLink3Url','custom link 3 url']
  };
  const normalized={}; Object.keys(row).forEach(k=>normalized[norm(k)]=row[k]);
  const obj={}; Object.entries(aliases).forEach(([field,names])=>{ let val=''; for(const name of names){ const n=norm(name); if(normalized[n]!==undefined){ val=normalized[n]; break; } } obj[field]=val; });
  if(!obj.title||!obj.author) return null; return migrateRecord(obj);
}
async function confirmImport(){ const existing=new Map(S.records.map((r,i)=>[keyFor(r),i])); let n=0,u=0,sk=0; const uploadSeen=new Set(); for(let i=0;i<importRows.length;i++){ const r=importRows[i]; const mode=$(`[data-import-mode="${i}"]`)?.value||'skip'; const k=keyFor(r); if(uploadSeen.has(k) && mode!=='skip'){ alert('Duplicate rows detected in the uploaded file. Skip duplicates or correct the file before importing.'); return; } uploadSeen.add(k); if(mode==='skip'){sk++; continue;} const idx=existing.get(k); if(idx!==undefined){ if(mode!=='update'){ alert(`Duplicate exists for ${r.title} by ${r.author}. Choose Update or Skip.`); return; } S.records[idx]={...S.records[idx],...r,id:S.records[idx].id,createdAt:S.records[idx].createdAt,updatedAt:new Date().toISOString()}; u++; } else { if(mode!=='new'){sk++; continue;} r.id=uid(); r.customSlug=r.customSlug||slugify(r.title); S.records.unshift(r); existing.set(k,0); n++; } } await persist(`Import completed: ${n} new, ${u} updated, ${sk} skipped. No duplicates created.`); activeTab='Records'; renderAdmin(); }
function altarTab(){
  const pubs=publicRecords(S).sort((a,b)=>String(a.title).localeCompare(b.title));
  const honored=(pubs.find(r=>normalizedAltar(r.altarStatus)==='Honored Record')||{}).id||'';
  const bright=pubs.filter(r=>normalizedAltar(r.altarStatus)==='Burning Bright').sort((a,b)=>(Number(a.sortOrder)||999)-(Number(b.sortOrder)||999)).map(r=>r.id).slice(0,3);
  const opts=(selected='', exclude=[])=>`<option value="">Select record...</option>`+pubs.filter(r=>!exclude.includes(r.id) || r.id===selected).map(r=>`<option value="${esc(r.id)}" ${selected===r.id?'selected':''}>${esc(r.title)} — ${esc(r.author)}</option>`).join('');
  return `<section class="panel"><h2>Ember Altar</h2><p class="section-note">The Ember Altar highlights existing Published Gilded/Sterling records. The Archives remain the complete curated collection.</p><div class="panel"><h3>Honored Record</h3><label>Select one record<select id="honoredSelect">${opts(honored, bright)}</select></label></div><div class="panel"><h3>Burning Bright</h3><div class="grid2"><label>Add record<select id="brightSelect">${opts('', [honored, ...bright])}</select></label><button id="addBright" type="button" class="btn ghost altar-add">Add to Burning Bright</button></div><p id="brightCount" class="section-note">Selected: ${bright.length} / 3</p><div id="brightList" class="simple-selected-list"></div></div><div class="panel"><h3>Homepage Preview</h3><div id="altarPreview" class="altar-preview-simple"></div></div><button id="saveAltar" class="btn primary">Save Ember Altar</button></section>`;
}
function wireAltar(){
  const pubs=publicRecords(S).sort((a,b)=>String(a.title).localeCompare(b.title));
  const find=id=>pubs.find(r=>r.id===id);
  const state={honored:($('#honoredSelect')?.value)||'', bright:pubs.filter(r=>normalizedAltar(r.altarStatus)==='Burning Bright').sort((a,b)=>(Number(a.sortOrder)||999)-(Number(b.sortOrder)||999)).map(r=>r.id).slice(0,3)};
  function optionHTML(selected='', exclude=[]){
    return `<option value="">Select record...</option>`+pubs.filter(r=>!exclude.includes(r.id) || r.id===selected).map(r=>`<option value="${esc(r.id)}" ${selected===r.id?'selected':''}>${esc(r.title)} — ${esc(r.author)}</option>`).join('');
  }
  function renderList(){
    state.bright=state.bright.filter(id=>id && id!==state.honored && find(id)).slice(0,3);
    $('#brightCount').textContent=`Selected: ${state.bright.length} / 3`;
    $('#brightList').innerHTML=state.bright.map((id,i)=>{const r=find(id); return `<div class="selected-simple-row"><img src="${esc(assetUrl(coverFor(r)||S.settings.favicon||'assets/logos/favicon.png'))}" alt=""><span><strong>${esc(r.title)}</strong><small>${esc(r.author)}</small></span><button class="btn small ghost" data-up="${id}" ${i===0?'disabled':''}>↑</button><button class="btn small ghost" data-down="${id}" ${i===state.bright.length-1?'disabled':''}>↓</button><button class="btn small danger" data-remove-bright="${id}">Remove</button></div>`;}).join('') || '<p class="muted">No Burning Bright records selected.</p>';
    $('#brightSelect').innerHTML=optionHTML('', [state.honored, ...state.bright]);
    $('#honoredSelect').innerHTML=optionHTML(state.honored, state.bright);
    renderPreview();
    $$('[data-remove-bright]').forEach(b=>b.onclick=()=>{state.bright=state.bright.filter(id=>id!==b.dataset.removeBright); renderList();});
    $$('[data-up]').forEach(b=>b.onclick=()=>{const i=state.bright.indexOf(b.dataset.up); if(i>0){[state.bright[i-1],state.bright[i]]=[state.bright[i],state.bright[i-1]]; renderList();}});
    $$('[data-down]').forEach(b=>b.onclick=()=>{const i=state.bright.indexOf(b.dataset.down); if(i>=0 && i<state.bright.length-1){[state.bright[i+1],state.bright[i]]=[state.bright[i],state.bright[i+1]]; renderList();}});
  }
  function renderPreview(){
    const h=find(state.honored);
    const bright=state.bright.map(find).filter(Boolean);
    $('#altarPreview').innerHTML=`<div><p class="eyebrow">Honored Record</p>${h?previewItem(h):'<p class="muted">None selected.</p>'}</div><div><p class="eyebrow">Burning Bright</p>${bright.length?bright.map(previewItem).join(''):'<p class="muted">None selected.</p>'}</div>`;
  }
  function previewItem(r){ return `<div class="preview-line"><img src="${esc(assetUrl(coverFor(r)||S.settings.favicon||'assets/logos/favicon.png'))}" alt=""><span><strong>${esc(r.title)}</strong><small>${esc(r.author)}</small></span></div>`; }
  $('#honoredSelect').onchange=e=>{state.honored=e.target.value; renderList();};
  $('#addBright').onclick=()=>{ const id=$('#brightSelect').value; if(!id) return toast('Choose a record first.'); if(state.bright.length>=3) return toast('Burning Bright allows up to 3 records.'); if(id===state.honored || state.bright.includes(id)) return toast('That record is already selected.'); state.bright.push(id); renderList(); };
  $('#saveAltar').onclick=async()=>{ S.records.forEach(r=>{ if(r.id===state.honored){ r.altarStatus='Honored Record'; r.sortOrder=''; } else if(state.bright.includes(r.id)){ r.altarStatus='Burning Bright'; r.sortOrder=String(state.bright.indexOf(r.id)+1); } else if(['Honored Record','Burning Bright'].includes(normalizedAltar(r.altarStatus))){ r.altarStatus='None'; r.sortOrder=''; } }); await persist('Ember Altar updated successfully.'); renderList(); };
  renderList();
}

function atmoTab(){ return `<section class="panel"><h2>Atmospheres & Audio</h2><p class="section-note">Gilded defaults to Embers. Sterling defaults to Celestial. Manual record settings override defaults.</p><div class="grid2"><label>Homepage Audio URL<input id="homepageAudio" value="${esc(S.settings.homepageAudio)}"></label>${uploadButton('uploadHomepageAudio','Upload Homepage Audio','audio/*')}<label>Archive Transition Audio URL<input id="archiveTransitionAudio" value="${esc(S.settings.archiveTransitionAudio)}"></label>${uploadButton('uploadArchiveAudio','Upload Archive Audio','audio/*')}<label>Default Volume<input id="audioVolume" type="number" step="0.05" min="0" max="1" value="${esc(S.settings.audioVolume)}"></label><label class="check"><input type="checkbox" id="audioEnabled" ${S.settings.audioEnabled?'checked':''}> Audio enabled</label></div><h3>Atmosphere Library</h3>${ATMOS.map(a=>{const x=S.settings.atmospheres[a];return `<div class="panel"><h3>${a}</h3><div class="grid2"><label>Description<input data-atmo-desc="${a}" value="${esc(x.description)}"></label><label>Default Tint<input data-atmo-tint="${a}" value="${esc(x.defaultTint)}"></label><label>Visual URL/Image/Video<input data-atmo-visual="${a}" value="${esc(x.visual)}"></label>${uploadButton('uploadAtmoVisual'+a,'Upload '+a+' Visual','image/*,video/*')}<label>Audio URL<input data-atmo-audio="${a}" value="${esc(x.audio)}"></label>${uploadButton('uploadAtmoAudio'+a,'Upload '+a+' Audio','audio/*')}</div></div>`}).join('')}<button id="saveAtmo" class="btn primary">Save Atmospheres & Audio</button></section>`; }
function wireAtmo(){ $('#saveAtmo').onclick=async()=>{ S.settings.homepageAudio=$('#homepageAudio').value; S.settings.archiveTransitionAudio=$('#archiveTransitionAudio').value; S.settings.audioVolume=Number($('#audioVolume').value)||.25; S.settings.audioEnabled=$('#audioEnabled').checked; ATMOS.forEach(a=>{Object.assign(S.settings.atmospheres[a],{description:$(`[data-atmo-desc="${a}"]`).value,defaultTint:$(`[data-atmo-tint="${a}"]`).value,visual:$(`[data-atmo-visual="${a}"]`).value,audio:$(`[data-atmo-audio="${a}"]`).value});}); await persist('Atmospheres saved.');}; [['uploadHomepageAudio','homepageAudio','video'],['uploadArchiveAudio','archiveTransitionAudio','video']].forEach(([u,target,type])=>{const el=$('#'+u); if(el) el.onchange=async e=>{const url=await uploadCloudinary(e.target.files[0],type); if(url){$('#'+target).value=url; toast('Media uploaded.');}}}); ATMOS.forEach(a=>{const v=$('#uploadAtmoVisual'+a); if(v) v.onchange=async e=>{const file=e.target.files[0]; const type=file?.type?.startsWith('video')?'video':'image'; const url=await uploadCloudinary(file,type); if(url){$(`[data-atmo-visual="${a}"]`).value=url; toast('Visual uploaded.');}}; const au=$('#uploadAtmoAudio'+a); if(au) au.onchange=async e=>{const url=await uploadCloudinary(e.target.files[0],'video'); if(url){$(`[data-atmo-audio="${a}"]`).value=url; toast('Audio uploaded.');}};}); }

const THEME_SWATCHES=[['Plum','#2f1c36'],['Deep Plum','#151017'],['Charcoal','#111015'],['Gold','#c9a84c'],['Antique Gold','#a9792b'],['Silver','#c9c2b8'],['Parchment','#e6dcc7'],['Ember','#d45a1e'],['Forest','#2f5a3b'],['Storm Blue','#445069'],['Crimson','#7b2632'],['Hearth Brown','#6e4a2f']];
function colorControl(id,label,value){ return `<div class="color-control"><label>${label}<input id="${id}" value="${esc(value)}" placeholder="#c9a84c"></label><div class="swatch-grid" data-color-target="${id}">${THEME_SWATCHES.map(([name,hex])=>`<button type="button" class="swatch ${String(value).toLowerCase()===hex.toLowerCase()?'selected':''}" data-color="${hex}" style="--sw:${hex}" title="${esc(name)}"><span>${esc(name)}</span></button>`).join('')}</div><p class="muted">Custom hex code is optional.</p></div>`; }
function settingsTab(){
  const seals=['Gilded','Sterling','Flicker','Ash'].map(d=>`<label>${d}<input data-seal="${d}" value="${esc(S.settings.seals[d]||'')}"></label>${uploadButton('uploadSeal'+d,'Upload '+d+' Seal')}`).join('');
  const fieldLabels=Object.keys(S.settings.fieldLabels||{}).map(k=>`<label>${esc(k)}<input data-field-label="${esc(k)}" value="${esc(S.settings.fieldLabels[k])}"></label>`).join('');
  const decreeSettings=['Gilded','Sterling','Flicker','Ash'].map(d=>`<label>${d} Title<input data-decree-title="${d}" value="${esc(S.settings.decreeSettings?.[d]?.title||d+' Decree')}"></label><label>${d} Description<textarea data-decree-desc="${d}">${esc(S.settings.decreeSettings?.[d]?.description||'')}</textarea></label>`).join('');
  return `<section class="panel"><h2>Settings</h2><h3>Branding</h3><div class="grid2"><label>Site Title<input id="siteTitle" value="${esc(S.settings.siteTitle)}"></label><label>Tagline<input id="tagline" value="${esc(S.settings.tagline)}"></label><label>Sanctum Logo URL<input id="sanctumLogo" value="${esc(S.settings.sanctumLogo)}"></label>${uploadButton('uploadSanctumLogo','Upload Sanctum Logo')}<label>Footer Logo URL<input id="footerLogo" value="${esc(S.settings.footerLogo)}"></label>${uploadButton('uploadFooterLogo','Upload Footer Logo')}<label>Favicon URL<input id="favicon" value="${esc(S.settings.favicon)}"></label>${uploadButton('uploadFavicon','Upload Favicon')}<label>Threshold URL<input id="thresholdUrl" value="${esc(S.settings.thresholdUrl)}"></label><label>Instagram URL<input id="instagramUrl" value="${esc(S.settings.instagramUrl)}"></label></div><h3>Appearance</h3><div class="grid2"><label>Homepage Background Image/Video URL<input id="homepageVisual" value="${esc(S.settings.homepageVisual)}"></label>${uploadButton('uploadHomepageVisual','Upload Homepage Visual','image/*,video/*')}<label>Homepage Overlay Opacity <span class="muted">0 = clearer video, 1 = darker</span><input id="homepageOverlayOpacity" type="range" min="0" max="1" step="0.05" value="${esc(S.settings.homepageOverlayOpacity)}"><output id="homepageOverlayOpacityOut">${esc(S.settings.homepageOverlayOpacity)}</output></label><label>Homepage Blur<input id="homepageOverlayBlur" type="number" min="0" max="20" step="1" value="${esc(S.settings.homepageOverlayBlur)}"></label>${colorControl('homepageOverlayColor','Homepage Overlay Color',S.settings.homepageOverlayColor)}${colorControl('primaryBg','Primary Background Color',S.settings.primaryBg)}${colorControl('accentColor','Accent Color',S.settings.accentColor)}${colorControl('headingColor','Heading Text Color',S.settings.headingColor)}${colorControl('bodyTextColor','Body Text Color',S.settings.bodyTextColor)}${colorControl('buttonColor','Button Color',S.settings.buttonColor)}<label>Heading Font<select id="fontHeading"><option ${S.settings.fontHeading==='Cormorant Garamond'?'selected':''}>Cormorant Garamond</option><option ${S.settings.fontHeading==='IM Fell English'?'selected':''}>IM Fell English</option><option ${S.settings.fontHeading==='Special Elite'?'selected':''}>Special Elite</option><option ${S.settings.fontHeading==='Georgia'?'selected':''}>Georgia</option></select></label><label>Body Font<select id="fontBody"><option ${S.settings.fontBody==='Cormorant Garamond'?'selected':''}>Cormorant Garamond</option><option ${S.settings.fontBody==='IM Fell English'?'selected':''}>IM Fell English</option><option ${S.settings.fontBody==='Special Elite'?'selected':''}>Special Elite</option><option ${S.settings.fontBody==='Georgia'?'selected':''}>Georgia</option></select></label></div><h3>Archive Whisper</h3><div class="grid2"><label class="check"><input type="checkbox" id="whisperEnabled" ${S.settings.archiveWhisper?.enabled?'checked':''}> Enable Archive Whisper</label><label>Whisper Label<input id="whisperLabel" value="${esc(S.settings.archiveWhisper?.label||'The Archives Whisper')}"></label><label>Whisper Destination URL<input id="whisperUrl" value="${esc(S.settings.archiveWhisper?.url||'')}"></label></div><div class="check-grid"><label class="check"><input type="checkbox" id="whisperHome" ${S.settings.archiveWhisper?.placements?.home?'checked':''}> Homepage</label><label class="check"><input type="checkbox" id="whisperArchives" ${S.settings.archiveWhisper?.placements?.archives?'checked':''}> Archives page</label><label class="check"><input type="checkbox" id="whisperRecords" ${S.settings.archiveWhisper?.placements?.records?'checked':''}> Record pages</label><label class="check"><input type="checkbox" id="whisperFooter" ${S.settings.archiveWhisper?.placements?.footer?'checked':''}> Footer</label></div><h3>Cloudinary</h3><div class="grid2"><label>Cloudinary Cloud Name<input id="cloudName" value="${esc(S.settings.cloudinary.cloudName)}"></label><label>Cloudinary Unsigned Upload Preset<input id="uploadPreset" value="${esc(S.settings.cloudinary.uploadPreset)}"></label></div><label>Correspondence Success Message<textarea id="correspondenceSuccess">${esc(S.settings.correspondenceSuccess)}</textarea></label><h3>Field Labels</h3><div class="grid2">${fieldLabels}</div><h3>Decree Settings</h3><div class="grid2">${decreeSettings}</div><h3>Decree Seals</h3><div class="grid2">${seals}</div><div class="toolbar"><button id="saveSettings" class="btn primary">Save All Settings</button><button id="restoreTheme" type="button" class="btn ghost">Restore Default Theme</button></div></section>`; }

function wireSettings(){
  const op=$('#homepageOverlayOpacity'), out=$('#homepageOverlayOpacityOut'); if(op&&out) op.oninput=()=>out.textContent=op.value;
  $$('[data-color-target] .swatch').forEach(btn=>btn.onclick=()=>{ const target=$('#'+btn.closest('[data-color-target]').dataset.colorTarget); target.value=btn.dataset.color; btn.closest('[data-color-target]').querySelectorAll('.swatch').forEach(x=>x.classList.remove('selected')); btn.classList.add('selected'); });
  $('#restoreTheme').onclick=()=>{ $('#homepageOverlayColor').value='#2f1c36'; $('#homepageOverlayOpacity').value=.72; $('#homepageOverlayOpacityOut').textContent='.72'; $('#homepageOverlayBlur').value=0; $('#primaryBg').value='#151017'; $('#accentColor').value='#c9a84c'; $('#headingColor').value='#f2dfaf'; $('#bodyTextColor').value='#efe7da'; $('#buttonColor').value='#c9a84c'; $('#fontHeading').value='Cormorant Garamond'; $('#fontBody').value='Cormorant Garamond'; toast('Default theme restored. Save All Settings to apply.'); };
  $('#saveSettings').onclick=async()=>{ Object.assign(S.settings,{siteTitle:$('#siteTitle').value,tagline:$('#tagline').value,sanctumLogo:$('#sanctumLogo').value,footerLogo:$('#footerLogo').value,favicon:$('#favicon').value,thresholdUrl:$('#thresholdUrl').value,instagramUrl:$('#instagramUrl').value,correspondenceSuccess:$('#correspondenceSuccess').value,homepageVisual:$('#homepageVisual').value,homepageOverlayColor:$('#homepageOverlayColor').value,homepageOverlayOpacity:Number($('#homepageOverlayOpacity').value),homepageOverlayBlur:Number($('#homepageOverlayBlur').value)||0,primaryBg:$('#primaryBg').value,accentColor:$('#accentColor').value,headingColor:$('#headingColor').value,bodyTextColor:$('#bodyTextColor').value,buttonColor:$('#buttonColor').value,fontHeading:$('#fontHeading').value,fontBody:$('#fontBody').value}); S.settings.cloudinary={cloudName:$('#cloudName').value,uploadPreset:$('#uploadPreset').value}; S.settings.archiveWhisper={enabled:!!$('#whisperEnabled')?.checked,label:$('#whisperLabel')?.value||'The Archives Whisper',url:$('#whisperUrl')?.value||'',placements:{home:!!$('#whisperHome')?.checked,archives:!!$('#whisperArchives')?.checked,records:!!$('#whisperRecords')?.checked,footer:!!$('#whisperFooter')?.checked}}; $$('[data-field-label]').forEach(i=>S.settings.fieldLabels[i.dataset.fieldLabel]=i.value); $$('[data-decree-title]').forEach(i=>{S.settings.decreeSettings[i.dataset.decreeTitle]=S.settings.decreeSettings[i.dataset.decreeTitle]||{};S.settings.decreeSettings[i.dataset.decreeTitle].title=i.value}); $$('[data-decree-desc]').forEach(i=>{S.settings.decreeSettings[i.dataset.decreeDesc]=S.settings.decreeSettings[i.dataset.decreeDesc]||{};S.settings.decreeSettings[i.dataset.decreeDesc].description=i.value}); $$('[data-seal]').forEach(i=>S.settings.seals[i.dataset.seal]=i.value); applyThemeVars(S); await persist('Settings updated successfully.'); };
  [['uploadSanctumLogo','sanctumLogo','image'],['uploadFooterLogo','footerLogo','image'],['uploadFavicon','favicon','image'],['uploadHomepageVisual','homepageVisual','auto']].forEach(([u,target,type])=>{const el=$('#'+u); if(el) el.onchange=async e=>{const file=e.target.files[0]; const rt=type==='auto'?(file?.type?.startsWith('video')?'video':'image'):type; const url=await uploadCloudinary(file,rt); if(url){$('#'+target).value=url; toast('Media uploaded.');}}});
  ['Gilded','Sterling','Flicker','Ash'].forEach(d=>{const el=$('#uploadSeal'+d); if(el) el.onchange=async e=>{const url=await uploadCloudinary(e.target.files[0],'image'); if(url){$(`[data-seal="${d}"]`).value=url; toast('Seal uploaded.');}}});
}


// v5.10 additions: Collections, Messages, Analytics
function collectionsTab(){ return `<section class="panel"><h2>Threads</h2><p class="section-note">Create reusable discovery threads for the Archives. Records can belong to multiple threads.</p><label class="check"><input type="checkbox" id="collectionsEnabledTab" ${S.settings.collectionsEnabled?'checked':''}> Enable Threads filter in Archives</label><div class="toolbar"><button class="btn primary" id="addCollection">Add Thread</button></div><div id="collectionsList" class="record-admin-list"></div></section>`; }
function collectionRow(c){ return `<div class="admin-row collection-row" data-collection-row="${esc(c.id)}"><div><strong>${esc(c.name||'Untitled Thread')}</strong><div class="muted">${esc(c.status||'Active')} · Order ${esc(c.displayOrder||0)} · ${esc(c.description||'No description')}</div></div><div class="toolbar"><button class="btn small" data-edit-collection="${esc(c.id)}">Edit</button><button class="btn small danger" data-delete-collection="${esc(c.id)}">Delete</button></div></div>`; }
function collectionEditor(c={}){ const id=c.id||slugify(c.name||`collection-${Date.now()}`); return `<div class="panel collection-editor"><h3>${c.id?'Edit':'Add'} Thread</h3><div class="grid2"><label>Name<input id="collectionName" value="${esc(c.name||'')}"></label><label>Status<select id="collectionStatus"><option ${c.status==='Active'?'selected':''}>Active</option><option ${c.status==='Inactive'?'selected':''}>Inactive</option><option ${c.status==='Draft'?'selected':''}>Draft</option></select></label><label>Display Order<input id="collectionOrder" type="number" value="${esc(c.displayOrder||0)}"></label><label>Banner Image URL<input id="collectionBanner" value="${esc(c.bannerImage||'')}"></label></div><label>Description<textarea id="collectionDescription">${esc(c.description||'')}</textarea></label><div class="toolbar"><button class="btn primary" id="saveCollection" data-id="${esc(id)}">Save Collection</button><button class="btn ghost" id="cancelCollection">Cancel</button></div></div>`; }
function renderCollectionsList(){ const box=$('#collectionsList'); if(!box) return; box.innerHTML=(S.collections||[]).sort((a,b)=>(Number(a.displayOrder)||999)-(Number(b.displayOrder)||999)||String(a.name).localeCompare(b.name)).map(collectionRow).join('')||'<p class="muted">No threads yet.</p>'; }
function wireCollections(){ renderCollectionsList(); $('#collectionsEnabledTab')?.addEventListener('change',async e=>{S.settings.collectionsEnabled=e.target.checked; await persist('Threads setting saved.');}); $('#addCollection').onclick=()=>{ $('#collectionsList').insertAdjacentHTML('beforebegin', collectionEditor({})); wireCollectionEditor(); }; $$('[data-edit-collection]').forEach(btn=>btn.onclick=()=>{ const c=S.collections.find(x=>x.id===btn.dataset.editCollection); $('.collection-editor')?.remove(); $('#collectionsList').insertAdjacentHTML('beforebegin', collectionEditor(c)); wireCollectionEditor(); }); $$('[data-delete-collection]').forEach(btn=>btn.onclick=async()=>{ const id=btn.dataset.deleteCollection; if(!confirm('Delete this thread? It will be removed from records too.')) return; S.collections=(S.collections||[]).filter(c=>c.id!==id); S.records.forEach(r=>{r.collections=(r.collections||[]).filter(x=>x!==id);}); await persist('Thread deleted.'); renderAdmin(); }); }
function wireCollectionEditor(){ $('#cancelCollection').onclick=()=>$('.collection-editor')?.remove(); $('#saveCollection').onclick=async()=>{ const id=$('#saveCollection').dataset.id || slugify($('#collectionName').value); const c={id,name:$('#collectionName').value.trim(),status:$('#collectionStatus').value,displayOrder:Number($('#collectionOrder').value)||0,bannerImage:$('#collectionBanner').value.trim(),description:$('#collectionDescription').value.trim()}; if(!c.name){toast('Thread name is required.');return;} S.collections=S.collections||[]; const idx=S.collections.findIndex(x=>x.id===id); if(idx>=0) S.collections[idx]=c; else S.collections.push(c); await persist('Thread saved.'); renderAdmin(); }; }

function messagesTab(){ return `<section class="panel"><h2>Messages</h2><div class="toolbar"><button class="btn ghost" id="refreshMessages">Refresh Messages</button></div><div id="messagesList"><p class="muted">Loading messages...</p></div></section>`; }
async function loadMessages(){ const r=await fetch(SANCTUM.messagesEndpoint,{headers:{'x-admin-key':adminKey},cache:'no-store'}); if(!r.ok) throw new Error(await r.text()); const j=await r.json(); S.messages=j.messages||[]; }
function renderMessages(){ const box=$('#messagesList'); if(!box)return; const msgs=S.messages||[]; box.innerHTML=msgs.length?msgs.map(m=>`<article class="message-card ${m.archived?'archived':''}"><header><strong>${esc(m.name||'Anonymous')}</strong><span>${esc(new Date(m.createdAt).toLocaleString())}</span></header><p class="muted">${esc(m.reason||'Correspondence')} ${m.recordTitle?`· Regarding ${esc(m.recordTitle)}`:''} ${m.replyRequested?'· Reply requested':''}</p><p>${esc(m.message).replace(/\n/g,'<br>')}</p><div class="toolbar">${m.email?`<button class="btn small" data-copy-email="${esc(m.email)}">Copy Email</button><a class="btn small ghost" href="mailto:${esc(m.email)}?subject=${encodeURIComponent('Re: Your message to the Emberlight Sanctum')}">Reply</a>`:''}<button class="btn small" data-read="${esc(m.id)}">${m.read?'Mark Unread':'Mark Read'}</button><button class="btn small" data-archive="${esc(m.id)}">${m.archived?'Unarchive':'Archive'}</button><button class="btn small danger" data-delete-msg="${esc(m.id)}">Delete</button></div></article>`).join(''):'<p class="muted">No messages yet.</p>'; }
function wireMessagesAdmin(){ loadMessages().then(renderMessages).then(wireMessageButtons).catch(e=>$('#messagesList').innerHTML=`<p class="warn">Unable to load messages: ${esc(e.message)}</p>`); $('#refreshMessages').onclick=()=>wireMessagesAdmin(); }
async function updateMessage(id,patch){ const r=await fetch(SANCTUM.messagesEndpoint,{method:'PATCH',headers:{'content-type':'application/json','x-admin-key':adminKey},body:JSON.stringify({id,patch})}); if(!r.ok) throw new Error(await r.text()); await loadMessages(); renderMessages(); wireMessageButtons(); }
function wireMessageButtons(){ $$('[data-copy-email]').forEach(b=>b.onclick=async()=>{await navigator.clipboard.writeText(b.dataset.copyEmail); toast('Email copied.');}); $$('[data-read]').forEach(b=>b.onclick=()=>{const m=S.messages.find(x=>x.id===b.dataset.read); updateMessage(m.id,{read:!m.read});}); $$('[data-archive]').forEach(b=>b.onclick=()=>{const m=S.messages.find(x=>x.id===b.dataset.archive); updateMessage(m.id,{archived:!m.archived});}); $$('[data-delete-msg]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this message?'))return; const r=await fetch(SANCTUM.messagesEndpoint,{method:'DELETE',headers:{'content-type':'application/json','x-admin-key':adminKey},body:JSON.stringify({id:b.dataset.deleteMsg})}); if(!r.ok) alert(await r.text()); await loadMessages(); renderMessages(); wireMessageButtons();}); }

async function loadAnalytics(period='30'){ const r=await fetch(`${SANCTUM.analyticsEndpoint}?period=${encodeURIComponent(period)}`,{headers:{'x-admin-key':adminKey},cache:'no-store'}); if(!r.ok) throw new Error(await r.text()); return r.json(); }
function analyticsPanel(data){ if(!data) return ''; const records=(data.records||[]).slice(0,5).map(x=>`<li>${esc(x.title||x.recordId)} — ${x.views} views</li>`).join('')||'<li>No record views yet.</li>'; const links=(data.links||[]).slice(0,5).map(x=>`<li>${esc(x.label||x.url)} — ${x.clicks} clicks</li>`).join('')||'<li>No link clicks yet.</li>'; const cols=(data.collections||[]).slice(0,5).map(x=>`<li>${esc(x.name||x.collectionId)} — ${x.views} views</li>`).join('')||'<li>No thread views yet.</li>'; const w=data.whisper||{}; return `<section class="panel analytics-box"><h3>Archive Insights</h3><div class="toolbar"><select id="analyticsPeriod"><option value="1">Today</option><option value="7">Last 7 Days</option><option value="30" selected>Last 30 Days</option><option value="90">Last 90 Days</option><option value="all">All Time</option></select><button class="btn ghost" id="exportAnalytics">Export CSV</button></div><div class="stat-grid"><div class="stat"><span>Record Views</span><strong>${esc(data.totals?.recordViews||0)}</strong></div><div class="stat"><span>Thread Views</span><strong>${esc(data.totals?.collectionViews||0)}</strong></div><div class="stat"><span>Link Clicks</span><strong>${esc(data.totals?.linkClicks||0)}</strong></div><div class="stat"><span>Messages</span><strong>${esc((S.messages||[]).length)}</strong></div></div><div class="grid3"><div><h4>Records</h4><ol>${records}</ol></div><div><h4>Threads</h4><ol>${cols}</ol></div><div><h4>Links</h4><ol>${links}</ol></div></div><h4>Archive Whisper</h4><p>Times Shown: ${esc(w.shown||0)} · Clicks: ${esc(w.clicks||0)} · CTR: ${esc(w.ctr||'0%')}</p></section>`; }

function wireAnalyticsControls(data){ $('#analyticsPeriod')?.addEventListener('change',async e=>{ const d=await loadAnalytics(e.target.value); $('#analyticsPanel').innerHTML=analyticsPanel(d); wireAnalyticsControls(d); }); $('#exportAnalytics')?.addEventListener('click',()=>{ const rows=[['type','label','url_or_id','count']]; (data.records||[]).forEach(x=>rows.push(['record_views',x.title||x.recordId,x.recordId,x.views])); (data.collections||[]).forEach(x=>rows.push(['thread_views',x.name||x.collectionId,x.collectionId,x.views])); (data.links||[]).forEach(x=>rows.push(['link_clicks',x.label||'',x.url||'',x.clicks])); const w=data.whisper||{}; rows.push(['archive_whisper_times_shown',S.settings.archiveWhisper?.label||'',S.settings.archiveWhisper?.url||'',w.shown||0]); rows.push(['archive_whisper_clicks',S.settings.archiveWhisper?.label||'',S.settings.archiveWhisper?.url||'',w.clicks||0]); downloadFile('sanctum-analytics.csv',rows.map(r=>r.map(csvEscape).join(',')).join('\n'),'text/csv'); }); }
